{
  "name": "PI E-816压电定位控制器",
  "name_en": "PI E-816 Piezo Positioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于控制压电位移台或压电执行器进行精密定位的控制器。该设备支持将通道移动到目标位置、读取当前位置，并查询控制就绪状态、通道相关状态以及位置上下限，常用于显微镜对焦和纳米级定位实验。",
  "description_en": "A controller for precision positioning of a piezo stage or piezo actuator. It supports moving a channel to a target position, reading the current position, and querying control readiness, channel-related status, and motion limits. It is commonly used for microscope focusing and nanoscale positioning experiments.",
  "actions": [
    {
      "action_name": "auto-MoveTo",
      "description": "将指定压电通道移动到目标位置。",
      "description_en": "Move the specified piezo channel to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "读取指定压电通道的当前位置。",
      "description_en": "Read the current position of the specified piezo channel."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否已准备好进行控制或运动。",
      "description_en": "Query whether the controller is ready for control or motion."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "查询通道对象设置或关联状态。",
      "description_en": "Query the channel object setting or associated status."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "查询通道相位状态。",
      "description_en": "Query the channel phase status."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限制。",
      "description_en": "Get the minimum position limit for the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限制。",
      "description_en": "Get the maximum position limit for the specified channel."
    }
  ],
  "tag_hints": [
    "piezo positioning",
    "nanopositioning",
    "microscope focus control",
    "single-axis motion",
    "PI E-816",
    "piezo stage controller",
    "precision displacement control"
  ]
}

